css:
:root:not(.dark) [data-slot="sidebar"]{--foreground:#FFFFFF;--color-foreground:#FFFFFF;--muted-foreground:#CFC3CF;--color-muted-foreground:#CFC3CF;--placeholder:#CFC3CF;--color-placeholder:#CFC3CF;--accent:#522653;--color-accent:#522653;--accent-foreground:#FFFFFF;--color-accent-foreground:#FFFFFF;--secondary:#522653;--color-secondary:#522653;--secondary-foreground:#FFFFFF;--color-secondary-foreground:#FFFFFF;--muted:#522653;--color-muted:#522653;--border:#5D3A5E;--color-border:#5D3A5E;--input:#5D3A5E;--color-input:#5D3A5E;color:#FFFFFF;}
[data-thread-item]{border-radius:6px!important;}
[data-slot="button"],[data-slot="input"],[data-slot="select-trigger"]{border-radius:6px!important;}
[data-slot="composer-host"]{border-radius:8px!important;border:1px solid color-mix(in srgb,var(--foreground) 30%,transparent)!important;box-shadow:none!important;}
[data-slot="composer-host"]:focus-within{border-color:color-mix(in srgb,var(--foreground) 55%,transparent)!important;box-shadow:0 0 0 1px color-mix(in srgb,var(--foreground) 20%,transparent)!important;}
[data-user-message-bubble]{border-radius:8px!important;}
.chat-markdown-codeblock{border-radius:4px!important;border:1px solid var(--border);}
[data-slot="dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"]{border-radius:8px!important;border:1px solid var(--border)!important;box-shadow:0 4px 12px rgba(0,0,0,.12)!important;}
[data-slot="tooltip-popup"]{border-radius:6px!important;}
button.bg-message-action:disabled{background:color-mix(in srgb,var(--foreground) 10%,transparent)!important;color:var(--muted-foreground)!important;opacity:1!important;}
[data-slot="switch"][data-unchecked]{background:#8D8D8D!important;box-shadow:none!important;}
[data-slot="switch"][data-unchecked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
[data-slot="switch"][data-checked]{background:#007A5A!important;box-shadow:none!important;}
[data-slot="switch"][data-checked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
::-webkit-scrollbar{width:10px;height:10px;}
::-webkit-scrollbar-thumb{background:color-mix(in srgb,var(--foreground) 22%,transparent);border-radius:999px;border:2px solid transparent;background-clip:padding-box;}
